#!/usr/bin/env python3
"""Build both static language pages from the actual app catalog; no network or analytics."""
from pathlib import Path
import json,html,hashlib,re
R=Path(__file__).resolve().parent.parent
catalog=json.loads((R/'docs/assets/catalog.json').read_text())
css_revision=hashlib.sha256((R/'docs/assets/site.css').read_bytes()).hexdigest()[:12]
source=(R/'Sources/NashiCore/FeatureCatalog.swift').read_text()
demo_catalog=dict(catalog)
for key in ['singleTools','multipleTools']:
 section=source.split('let '+key+':')[1].split('\n    ]')[0]
 demo_catalog[key]={k:re.findall(r'\.(\w+)',v) for k,v in re.findall(r'"(\w+)": \[([^\]]*)\]',section)}
# UI copy comes from the macOS app, just like the tool matrix.
# Keep marketing copy independent; the interactive preview follows native UI.
wheel_titles=dict(re.findall(r'\.(\w+): "([^"]+)"',source.split('let toolNames:')[1].split('\n    ]')[0]))
models=(R/'Sources/NashiCore/Models.swift').read_text().split('public enum ToolKind:')[1].split('public struct EditRect:')[0]
editor_titles=dict(re.findall(r'case \.(\w+): return "([^"]+)"',models))
editor=(R/'Sources/NashiApp/ToolEditor.swift').read_text()
def simple_switch(section):
 result={}
 for cases,value in re.findall(r'case ([^:\n]+):\s*return "([^"\\]*)"\s*\n',section):
  for key in re.findall(r'\.(\w+)',cases): result[key]=value
 return result
hints=simple_switch(editor.split('var toolHint:String')[1].split('var primaryTitle:String')[0])
primary=simple_switch(editor.split('var primaryTitle:String')[1].split('var canApply:Bool')[0])
# Browser equivalents of the native light/dark palette; no platform build required.
palette={key:{'light':light,'dark':dark} for key,light,dark in [
 ('Paper','#F9F6ED','#111A14'),('Ink','#243B2B','#E7EBE6'),
 ('Surface','#FFFEF7','#1C281F'),('Inset','#F1EDE0','#151F18'),
 ('Muted','#596650','#A9B5A8'),('Line','#DCDDD1','#344237'),
 ('Sage','#E0EBD2','#243928'),('Sand','#F6E7BE','#3C3421')]}
translations=json.loads((R/'Sources/NashiCore/Resources/Turkish.json').read_text())
feedback_source=(R/'Sources/NashiApp/WheelFeedback.swift').read_text()
feedback={'voices':int(re.search(r'for _ in 0\.\.<(\d+)',feedback_source)[1]),'volume':float(re.search(r'player.volume = ([\d.]+)',feedback_source)[1]),'minimumInterval':float(re.search(r'minimumInterval: TimeInterval = ([\d.]+)',feedback_source)[1])}
ui_strings=set(wheel_titles.values())|set(editor_titles.values())|set(hints.values())|set(primary.values())|{'Fine-tune it. Save a fresh copy.','Convert','Tools','Actions','Float','Copy','Move','Copy Path','Terminal','Original stays safe','PREVIEW','MAKE IT YOURS','Save a fresh copy','Icons','List','Clear','Close','Appearance','Light','Dark'}
demo_catalog['presentation']={'wheelTitles':wheel_titles,'editorTitles':editor_titles,'hints':hints,'primaryTitles':primary,'palette':palette,'feedback':feedback,'translations':{text:translations[text] for text in sorted(ui_strings) if text in translations}}
(R/'docs/assets/demo/catalog.json').write_text(json.dumps(demo_catalog,ensure_ascii=False,separators=(',',':')))
play_revision=hashlib.sha256(b''.join((R/p).read_bytes() for p in ['docs/assets/playground.js','docs/assets/playground.css','docs/assets/wheel-geometry.mjs','docs/assets/demo/catalog.json','docs/assets/demo/wheel-selection.wav'])).hexdigest()[:12]
media_revision=hashlib.sha256((R/'docs/assets/showcase/nashi-demo.mp4').read_bytes()).hexdigest()[:12]
features=[
('compress','Compress','Sıkıştır','Image, video, audio and PDF compression. Choose quality, reduction percentage or target size where supported. An unreachable target returns an explanation rather than silently losing features.','Görsel, video, ses ve PDF sıkıştırma. Desteklenen türlerde kalite, küçültme oranı veya hedef boyut seçilir; ulaşılamayan hedefler açıklanır.'),
('removeMetadata','Metadata','Metadata','Inspect, edit or remove supported image, PDF and media metadata, including track and chapter fields. Export a new copy.','Desteklenen görsel, PDF ve medya metadatasını incele, düzenle veya kaldır. Track/chapter alanları dahil; yeni kopya oluşturulur.'),
('editImage','Edit image','Görsel düzenle','Resize, rotate, flip and tune brightness, contrast and saturation, with an original/result preview.','Boyutlandır, döndür, yansıt; parlaklık, kontrast ve doygunluğu önizleyerek ayarla.'),
('annotateImage','Annotate','İşaretle','Independent freehand/marker and shape tools, text, arrows and Select / Move. Choose one drawing tool at a time.','Bağımsız serbest çizim/marker ve şekiller, metin, oklar ve Select / Move. Her çizim aracı tek başına çalışır.'),
('frameImage','Frame image','Çerçeve ekle','Create a polished image frame with configurable padding, background, corners and shadow.','Kenar boşluğu, arka plan, köşe ve gölge ayarlarıyla görsel çerçevesi oluştur.'),
('cropImage','Crop image','Görseli kırp','Drag to select, move or resize the crop. Hold Shift to lock its ratio; Return exports a cropped copy.','Sürükleyerek alan seç, taşı veya boyutlandır. Shift oranı kilitler; Enter kırpılmış kopyayı kaydeder.'),
('normalizeAudio','Normalize audio','Ses seviyesini eşitle','Analyze loudness, then export with integrated-loudness, loudness-range and true-peak targets.','Önce ses yüksekliği analiz edilir; hedef loudness, aralık ve true-peak değerleriyle kopya kaydedilir.'),
('muteVideo','Remove audio','Video sesini kaldır','Create a silent video copy while keeping the video stream.','Video akışını koruyarak sessiz bir kopya oluştur.'),
('trimVideo','Trim video','Video kırp','Preview, drag In/Out handles, move the selection and export its range. Keyboard playback, seeking and I/O marks help refine cuts.','Önizle, In/Out tutamaçlarını sürükle, seçimi taşı ve aralığı dışa aktar. Klavyeyle oynatma, gezinme ve I/O kesimi kolaylaştırır.'),
('splitPDF','Split PDF','PDF böl','Split selected pages into individual files or groups. Specify page ranges and pages per file.','Sayfa aralıklarını ve dosya başına sayfa sayısını seçerek PDF’yi tek tek veya gruplar halinde böl.'),
('organizePDF','Organize PDF','PDF düzenle','Reorder, remove and rotate pages. Optional uniform-width output is limited when document features cannot be safely preserved.','Sayfaları sırala, çıkar ve döndür. Eşit genişlik seçeneği, belge özelliklerinin güvenle korunabildiği dosyalarda kullanılır.'),
('extractArchive','Extract archives','Arşiv aç','Extract ZIP, TAR, GZIP and RAR into a new folder. Path and link validation keeps entries inside that folder.','ZIP, TAR, GZIP ve RAR arşivlerini yeni klasöre çıkar. Yol ve link denetimleri klasör dışına yazmayı engeller.'),
('createPDF','Images to PDF','Görsellerden PDF','Combine selected images into a new PDF in the chosen order.','Seçili görselleri istenen sırayla yeni bir PDF’de birleştir.'),
('mergePDF','Merge PDFs','PDF birleştir','Combine several PDFs while preserving supported page content and navigation. Originals remain unchanged.','Birden fazla PDF’yi desteklenen sayfa içeriği ve gezinme özellikleri korunarak birleştir; orijinaller değişmez.'),
('cropVideo','Crop video','Video alanını kırp','Select a region directly on the video preview. Drag, resize, use Shift ratio lock and Return to export.','Video önizlemesinde alan seç. Sürükle, boyutlandır; Shift ile oranı kilitle, Enter ile kopyayı dışa aktar.'),
('changeVideoSpeed','Change speed','Video hızını değiştir','Change video speed with matching audio tempo and preview controls.','Önizleme kontrolleriyle video hızını ve buna eşlik eden ses temposunu değiştir.'),
('joinVideos','Join videos','Videoları birleştir','Join multiple clips in order, adapting geometry, frame rate and audio layout to a consistent output.','Klipleri sırayla birleştir; boyut, kare hızı ve ses düzeni tutarlı bir çıktıya uyarlanır.'),
('videoSnapshots','Video snapshots','Videodan kare al','Choose timestamps and save still frames as new PNG files.','Zaman noktalarını seçip kareleri yeni PNG dosyaları olarak kaydet.'),
('splitVideo','Split video','Video böl','Split at markers, equal clip counts or intervals. Remove unwanted segments; save separately or join retained clips.','İşaretlerden, eşit klip sayısından veya aralıklardan böl. İstenmeyen parçaları çıkar; kalanları ayrı veya birleşik kaydet.'),
('audioToVideo','Audio to video','Sesten video','Create a waveform, spectrum, frequency-bar or still-image video from an audio file.','Ses dosyasından waveform, spektrum, frekans çubukları veya sabit görselle video oluştur.'),
('trimAudio','Trim audio','Ses kırp','Waveform preview, In/Out handles and selected-range playback. Optional silence trimming and keyboard seeking.','Waveform önizleme, In/Out tutamaçları ve seçili aralığı oynatma. İsteğe bağlı sessizlik kesme ve klavyeyle gezinme.'),
('audioChannels','Audio channels','Ses kanalları','Convert mono/stereo and set left/right levels, with channel previews.','Mono/stereo dönüşümü yap, sol/sağ seviyelerini ayarla ve kanalları önizle.'),
('createCollage','Create collage','Kolaj oluştur','Arrange several images in a configurable layout with gaps and background styling.','Birden fazla görseli aralık ve arka plan ayarlarıyla düzenlenebilir bir kolajda birleştir.'),
('redactImage','Redact image','Görselde gizle','Select areas and export with solid, blur or pixelation treatments. Always verify the resulting file before sharing.','Alan seçip düz renk, blur veya pikselleştirme uygula. Paylaşmadan önce çıktıyı kontrol et.'),
('redactVideo','Redact video','Videoda gizle','Define rectangular regions and time ranges for solid, blur or pixelated redaction.','Düz renk, blur veya pikselleştirme için dikdörtgen alanlar ve zaman aralıkları seç.'),
('redactAudio','Redact audio','Seste gizle','Choose intervals to replace with a bleep or silence; preserve the rest of the audio.','Bleep veya sessizlikle değiştirilecek aralıkları seç; sesin geri kalanı korunur.'),
('readQRCode','Read QR codes','QR kod oku','Scan supported images and PDF pages, review detected contents and export a report.','Desteklenen görsel ve PDF sayfalarını tara; bulunan içerikleri inceleyip rapor dışa aktar.')]
assert set(x[0] for x in features)==set(catalog['tools'])
shortcuts=[('⇧ + drag','Convert wheel','Dönüştürme çarkı'),('⌘ + drag','Tools wheel','Araç çarkı'),('⌃ + drag','File actions wheel','Dosya işlemleri çarkı'),('⌃ ⇧ D','Download a copied web link','Kopyalanmış web linkini indir'),('← ↑ / → ↓','Previous / next wheel item','Önceki / sonraki çark öğesi'),('Home / End','First / last wheel item','İlk / son çark öğesi'),('Enter / Space','Choose highlighted wheel item','Çarktaki seçili öğeyi uygula'),('Esc / Tab','Close wheel','Çarkı kapat'),('Space','Play / pause in supported media editors','Medya editörlerinde oynat / duraklat'),('← / →','Seek backward / forward 1 second','1 saniye geri / ileri git'),('⇧ ← / ⇧ →','Video: 1 frame; audio: 0.1 second','Video: 1 kare; ses: 0,1 saniye'),('I / O','Set selection In / Out','Seçimin In / Out noktasını belirle'),('⇧ Space','Play the selected range','Seçili aralığı oynat'),('M','Add a split marker where supported','Desteklenen araçlarda bölme işareti ekle'),('Home / End','Go to beginning / end of preview','Önizlemenin başına / sonuna git'),('⇧ + crop drag','Lock crop aspect ratio','Crop en-boy oranını kilitle'),('Enter','Export crop in the crop editor','Crop editöründe kırpılmış kopyayı kaydet'),('⌘ S','Save from supported editors','Desteklenen editörlerde kaydet'),('⌘ ,','Open settings','Ayarları aç'),('⌘ Q','Quit Nashi','Nashi’den çık')]
E=html.escape
def showcase(assets,tr):
 choose=lambda en,tt:tt if tr else en
 video_url=f'{assets}showcase/nashi-demo.mp4?v={media_revision}'
 poster_url=f'{assets}showcase/demo-poster.jpg?v={media_revision}'
 shots=[
  ('mac-home.png','macOS · Home','macOS · Ana ekran','Choose files and get to your next step.','Dosya seç ve bir sonraki adıma geç.'),
  ('mac-crop.png','macOS · Crop image','macOS · Görsel kırp','Drag a selection, lock its ratio and save a fresh copy.','Alanı sürükleyerek seç, oranı kilitle ve yeni kopyayı kaydet.'),
  ('mac-trim.png','macOS · Trim video','macOS · Video kırp','Preview a clip, drag In/Out and save the selected range.','Klibi önizle, In/Out tutamaçlarını sürükle ve seçilen aralığı kaydet.')]
 gallery=''.join(f'<figure class="screenshot-card"><a href="{assets}showcase/{name}"><img src="{assets}showcase/{name}" alt="{E(choose(en,tt))}" loading="lazy" width="{820 if name=="mac-home.png" else 1000}" height="{780 if name=="mac-home.png" else 760}"></a><figcaption><strong>{E(choose(en,tt))}</strong><span>{E(choose(desc,tdesc))}</span></figcaption></figure>' for name,en,tt,desc,tdesc in shots)
 return f'''<section id="demo" class="showcase">
<div class="section-heading"><span class="eyebrow">{choose('See it for yourself','Kendin gör')}</span><h2>{choose('Nashi, in real life.','Nashi, gerçek kullanımda.')}</h2><p>{choose('A 95-second real screen recording of macOS 0.7.3: Finder drag, the conversion wheel, image crop and video trim. Pauses and longer previews are shortened; retained actions play at normal speed.','macOS 0.7.3 ile çekilmiş 95 saniyelik gerçek ekran kaydı: Finder sürükleme, wheel, dönüştürme, görsel kırpma ve video trim. Beklemeler ve uzun önizlemeler kısaltıldı; kalan hareketler normal hızda oynar.')}</p></div>
<div class="demo-player"><video controls playsinline preload="metadata" poster="{poster_url}" width="1440" height="810" aria-label="{choose('Nashi real screen recording','Nashi gerçek kullanım ekran kaydı')}"><source src="{video_url}" type="video/mp4"><track kind="captions" src="{assets}showcase/demo-en.vtt?v={media_revision}" srclang="en" label="English" {'' if tr else 'default'}><track kind="captions" src="{assets}showcase/demo-tr.vtt?v={media_revision}" srclang="tr" label="Türkçe" {'default' if tr else ''}><a href="{video_url}">{choose('Open the MP4 demo','MP4 demoyu aç')}</a></video></div>
<p class="demo-links"><a href="{video_url}">{choose('Open / download MP4 ↗','MP4 aç / indir ↗')}</a><span>{choose('Silent · English / Turkish captions · No autoplay','Sessiz · Türkçe / İngilizce altyazı · Otomatik oynatma yok')}</span></p>
<details class="demo-transcript"><summary>{choose('Read the tour','Turu metin olarak oku')}</summary><ol><li>{choose('Drag an image in Finder while holding Shift.','Finder’da görseli sürüklerken Shift’e bas.')}</li><li>{choose('Drop on JPG in the conversion wheel to create a new copy.','Dönüştürme çarkında JPG’nin üzerine bırakarak yeni kopya oluştur.')}</li><li>{choose('In Crop Image, drag a selection. Shift locks the aspect ratio; Return saves a cropped copy.','Crop Image içinde alanı sürükleyerek seç. Shift oranı kilitler; Enter kırpılmış kopyayı kaydeder.')}</li><li>{choose('Drag a video while holding Command, then choose Trim Video. Space controls playback; drag In and Out to set the range. Preview it and save a fresh trimmed copy.','Videoyu Command ile sürükleyip Trim Video’yu seç. Space ile oynat; In/Out tutamaçlarıyla aralığı belirle. Seçimi önizle ve yeni klibi kaydet.')}</li><li>{choose('Find the outputs in Freshly made and Finder. The demo creates a JPG, a 410×410 crop and a 7.07-second trimmed clip from a 12-second source; originals remain unchanged.','Çıktıları Freshly made ve Finder’da bul. Demoda JPG, 410×410 kırpılmış görsel ve 12 saniyelik kaynaktan 7,07 saniyelik klip oluşturulur; orijinaller korunur.')}</li></ol></details>
<div class="screenshot-grid">{gallery}</div>
<p class="subtle">{choose('Mac screenshots: 0.7.3.','Mac ekranları: 0.7.3.')} {choose('Demo files use Nashi artwork only. Click any screenshot to see it in full.','Demo dosyalarında yalnızca Nashi görselleri kullanılır. Tam boyut için ekran görüntüsüne tıkla.')}</p>
</section>'''

for language in ['en','tr']:
 tr=language=='tr';prefix='../' if tr else '';assets=prefix+'assets/';choose=lambda en,tt:tt if tr else en
 title=choose('Your files.<br><em>Without the fuss.</em>','Dosyaların.<br><em>Akışını bozmadan.</em>')
 cards=''.join(f'<article class="tool"><span class="tool-number">{i+1:02}</span><h3>{E(x[2] if tr else x[1])}</h3><p>{E(x[4] if tr else x[3])}</p><button class="try-tool" data-try-tool="{x[0]}">{choose("Try this tool","Bu aracı dene")} ↗</button></article>' for i,x in enumerate(features))
 table=''.join('<tr><th scope="row">'+E(ext.upper())+'</th><td>'+', '.join(E(x.upper()) for x in dest)+'</td></tr>' for ext,dest in catalog['conversionMatrix'].items())
 keys=''.join(f'<tr><th scope="row"><kbd>{E(key)}</kbd></th><td>{E(tt if tr else en)}</td></tr>' for key,en,tt in shortcuts)
 doc=f'''<!doctype html>
<html lang="{language}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src 'self' blob: data:; media-src 'self' blob:; style-src 'self' 'unsafe-inline'; script-src 'self'; connect-src 'self' blob:; base-uri 'none'; form-action 'none'">
<meta name="description" content="{choose('Nashi: open-source local file conversion, editing, web downloads and a playful drag wheel. All features, formats and keyboard shortcuts.','Nashi: açık kaynaklı yerel dosya dönüştürme, düzenleme, web indirme ve sürükleme çarkı. Tüm özellikler, formatlar ve kısayollar.')}">
<title>Nashi — {choose('Your files, a little sweeter','Dosyaların için tatlı bir kolaylık')}</title><link rel="icon" href="{assets}nashi.png"><link rel="stylesheet" href="{assets}site.css?v={css_revision}"><link rel="stylesheet" href="{assets}playground.css?v={play_revision}"><script src="{assets}vendor/pdf-lib.min.js" defer></script><script src="{assets}playground.js?v={play_revision}" defer></script></head>
<body><a class="skip" href="#main">{choose('Skip to content','İçeriğe geç')}</a><header><a class="brand" href="#"><img src="{assets}nashi.png" alt="" width="42" height="42">Nashi</a><nav aria-label="{choose('Main navigation','Ana gezinme')}"><a href="#playground">{choose("Try it","Dene")}</a><a href="#features">{choose('Features','Özellikler')}</a><a href="#formats">{choose('Formats','Formatlar')}</a><a href="#shortcuts">{choose('Shortcuts','Kısayollar')}</a><a href="{('../index.html' if tr else 'tr/index.html')}">{'EN' if tr else 'TR'}</a><a class="nav-github" href="https://github.com/orkunisitmak/nashi-app">GitHub ↗</a></nav></header>
<main id="main"><section class="hero"><span class="eyebrow">macOS · {choose('FREE & OPEN SOURCE','ÜCRETSİZ & AÇIK KAYNAK')}</span><h1>{title}</h1><p class="intro">{choose('Drag a file. Tap a key. Make it yours. Convert, crop and fine-tune without breaking your flow.','Bir dosya sürükle. Bir tuşa bas. İstediğin hale getir. Dönüştür, kırp, düzenle; işine kaldığın yerden devam et.')}</p><div class="hero-actions"><a class="button primary" href="#download">{choose('Get Nashi','Nashi’yi indir')} ↓</a><a class="button secondary" href="#playground">{choose('Try in your browser','Tarayıcıda dene')} ↗</a></div><p class="subtle">{choose('Your files stay yours. Local processing. No subscription.','Dosyaların sende kalır. Yerel işlem. Abonelik yok.')}</p></section>
<section id="playground" aria-label="{choose('Interactive Nashi demo','Etkileşimli Nashi demosu')}"><div class="live-loading">{choose('Preparing your demo desktop…','Demo masaüstün hazırlanıyor…')}</div><noscript><p class="demo-noscript">{choose('Enable JavaScript to try the interactive playground. You can also watch the recording below.','Etkileşimli demo için JavaScript’i aç. Aşağıdaki gerçek kullanım kaydını da izleyebilirsin.')}</p></noscript></section>
<div class="demo-stats"><div><strong>275</strong><span>{choose('conversion routes','dönüşüm yolu')}</span></div><div><strong>27</strong><span>{choose('file tools','dosya aracı')}</span></div><div><strong>6</strong><span>{choose('ways to keep moving','dosya işlemi')}</span></div></div>

<section class="status" id="download"><div><span class="eyebrow">{choose('Download Nashi','Nashi’yi indir')}</span><h2>{choose('Ready for your files.','Dosyaların için hazır.')}</h2><p>{choose('This fork supports macOS only. Build from source using the repository instructions. Choose Set up tools once for verified media and Office runtime downloads. Core native image and PDF features work immediately.','Bu fork yalnızca macOS’u destekler. Depodaki adımlarla kaynak koddan derle. Medya/Office araçları için Set up tools ile bir kez doğrulanmış indirmeleri yap. Temel yerel görsel ve PDF özellikleri hemen çalışır.')}</p><p class="subtle">{choose('Source builds are not Apple-notarized; macOS may require first-launch approval.','Kaynak derlemelerinde Apple notarization yok; macOS ilk açılışta onay isteyebilir.')}</p></div><div class="platforms"><div><strong>macOS</strong><span>Apple Silicon · macOS 13+</span><a class="button primary" href="https://github.com/orkunisitmak/nashi-app/releases/latest/download/Nashi-macOS-arm64.zip">{choose('Upstream Mac ZIP','Upstream Mac ZIP')} ↗</a></div><a href="https://github.com/orkunisitmak/nashi-app/releases/latest">{choose('Upstream releases (not this fork)','Upstream sürümler (bu fork değil)')} ↗</a></div></section>
<section class="flow"><div class="section-heading"><span class="eyebrow">{choose('The everyday flow','Günlük kullanım')}</span><h2>{choose('One gesture. Many possibilities.','Tek hareket. Bir sürü olasılık.')}</h2></div><div class="flow-grid"><article><b>01</b><h3>{choose('Choose or drag','Seç veya sürükle')}</h3><p>{choose('Use Home or drag a file in Finder and hold Shift, Command or Control to open the matching wheel.','Ana ekrandan dosya seç veya Finder’da dosyayı sürüklerken Shift, Command ya da Control basılı tut.')}</p></article><article><b>02</b><h3>{choose('Make it yours','İstediğin hale getir')}</h3><p>{choose('Choose a format or tool. Preview edits and use keyboard controls for precise adjustments.','Formatı veya aracı seç. Düzenlemeyi önizle; hassas ayarlar için klavyeyi kullan.')}</p></article><article><b>03</b><h3>{choose('Save a fresh copy','Yeni kopyayı kaydet')}</h3><p>{choose('Watch real progress and save a new output. A short, borderless success card shows when it is ready.','Gerçek ilerlemeyi izle ve yeni çıktıyı kaydet. Tamamlandığında kısa, çerçevesiz bir bildirim görünür.')}</p></article></div></section>
<section id="features"><div class="section-heading"><span class="eyebrow">{choose('The Nashi toolbox','Nashi araç kutusu')}</span><h2>27 {choose('tools. Room to create.','araç. Üretmek için alan.')}</h2><p>{choose('The macOS tool catalog.','macOS araç kataloğu.')}</p></div><div class="tool-grid">{cards}</div></section>
<section class="web-feature"><span class="eyebrow">{choose('From the web to your workflow','Web’den iş akışına')}</span><h2>{choose('A link. A file. Yours to work with.','Bir link. Bir dosya. İşlemek sana kalmış.')}</h2><p>{choose('Paste a public video share link or direct media address. Choose video, MP3 or the original image/media, quality and destination. YouTube cards can offer video and thumbnail separately; Instagram reel cards need an actual reel link.','Public video paylaşım linkini veya doğrudan medya adresini yapıştır. Video, MP3 ya da orijinal görsel/medyayı; kaliteyi ve klasörü seç. YouTube kartlarında video ve thumbnail ayrı sunulabilir; Instagram reel kartlarında gerçek reel linki gerekir.')}</p><p>{choose('Use Control–Shift–D for a copied link, drag a browser card with Command, or drop it onto Home. Some players only expose a poster or blob address; Copy Share Link is the fallback. Supported sites change. Instagram photo posts open a photo picker; selected photos are saved in post order. Reels offer video and audio without a thumbnail action. DRM, live streams, login-required media, profile-wide downloads and video playlists are not supported.','Kopyalanmış link için Control–Shift–D kullan; tarayıcı kartını Command ile sürükle veya Ana ekrana bırak. Bazı oynatıcılar yalnızca poster/blob adresi verir; bu durumda paylaşım linkini kopyala. Site desteği değişebilir. Instagram fotoğraf gönderileri seçim listesi açar; seçilen görseller gönderi sırasıyla kaydedilir. Reels’te thumbnail seçeneği yoktur. DRM, canlı yayın, giriş gerektiren medya, tüm profil indirme ve video playlistleri desteklenmez.')}</p><button id="try-download" class="button secondary">{choose("Try the download flow","İndirme akışını dene")} ↗</button></section>
<section id="formats"><div class="section-heading"><span class="eyebrow">{choose('Formats, without the guesswork','Formatları açıkça gör')}</span><h2>45 {choose('inputs.','girdi.')} 275 {choose('routes.','dönüşüm yolu.')}</h2><p>{choose('This table is generated from the app catalog. A format appearing here does not mean every advanced document feature can be retained. PDF to DOCX/XLSX reconstruction is heuristic; PDF to PPTX uses page images.','Bu tablo uygulama kataloğundan üretilir. Bir formatın listelenmesi, her gelişmiş belge özelliğinin korunabildiği anlamına gelmez. PDF→DOCX/XLSX yeniden kurma sezgiseldir; PDF→PPTX sayfa görselleri kullanır.')}</p></div><label class="search-label" for="format-search">{choose('Find an input or output format','Girdi veya çıktı formatı ara')}</label><input id="format-search" type="search" placeholder="PNG, MP4, PDF…" autocomplete="off"><div class="table-wrap"><table id="format-table"><thead><tr><th>{choose('Input','Girdi')}</th><th>{choose('Available outputs','Çıktılar')}</th></tr></thead><tbody>{table}</tbody></table></div></section>
<section class="actions"><h2>{choose('Six ways to keep files moving.','Dosyaları ilerletmenin altı yolu.')}</h2><div class="action-list">{''.join('<span>'+E(v)+'</span>' for v in (['AirDrop','Float','Copy','Move','Copy path','Open in Terminal'] if not tr else ['AirDrop','Float rafı','Kopyala','Taşı','Yolu kopyala','Terminal’de aç']))}</div><p>{choose('Float keeps files in a small shelf. History can be searched, reused and revealed in Finder. Move explicitly moves originals; exports create new copies and do not overwrite existing names.','Float dosyaları küçük bir rafta tutar. Geçmişte ara, dosyaları yeniden kullan veya Finder’da göster. Taşı işlemi orijinali taşır; dışa aktarımlar yeni kopya oluşturur ve mevcut adların üzerine yazmaz.')}</p></section>
<section id="shortcuts"><div class="section-heading"><span class="eyebrow">{choose('Keep your hands in flow','Elin alışsın, işin hızlansın')}</span><h2>{choose('The shortcut sheet.','Kısayol rehberi.')}</h2><p>{choose('macOS defaults. Drag modifiers are customizable. Editor shortcuts apply where that action is available; text fields and native controls retain their normal input behavior.','macOS varsayılanları. Sürükleme tuşları özelleştirilebilir. Editör kısayolları ilgili işlem destekleniyorsa çalışır; metin alanları ve yerel kontroller normal davranışını korur.')}</p></div><div class="table-wrap"><table><thead><tr><th>{choose('Shortcut','Kısayol')}</th><th>{choose('Action','İşlem')}</th></tr></thead><tbody>{keys}</tbody></table></div></section>
{showcase(assets,tr)}
<section class="trust"><div><span class="eyebrow">{choose('Local first. Open by design.','Önce yerel. Tasarımı açık.')}</span><h2>{choose('Small footprint.<br>Clear boundaries.','Küçük araç.<br>Açık sınırlar.')}</h2></div><div><h3>{choose('Privacy','Gizlilik')}</h3><p>{choose('Conversion and editing run locally. Web downloads contact the chosen site. No analytics, cloud account, browser-cookie import or subscription is built in.','Dönüştürme ve düzenleme yerelde çalışır. Web indirmeleri seçilen siteye bağlanır. Analytics, bulut hesabı, tarayıcı çerezi aktarma veya abonelik bulunmaz.')}</p><h3>{choose('Manual updates','Elle güncelleme')}</h3><p>{choose('This fork has no built-in app updater. Install newer versions manually; external-tool setup remains available.','Bu fork’ta uygulama güncelleyicisi yoktur. Yeni sürümleri elle kur; harici araç kurulumu kullanılabilir.')}</p><h3>{choose('Transparent limitations','Açık sınırlamalar')}</h3><p>{choose('Complex document conversions are best-effort. Haptic feedback depends on hardware. macOS may show first-run warnings for builds without an OS-trusted publisher signature. We do not ask you to disable system security.','Karmaşık belge dönüşümleri her özelliği koruyamayabilir. Titreşim donanıma bağlıdır. İşletim sistemince güvenilen yayıncı imzası olmayan build’lerde macOS ilk açılış uyarıları gösterebilir. Sistem güvenliğini kapatmanız istenmez.')}</p></div></section>
<section class="inspiration"><h2>{choose('Inspired. Independently made.','İlham alındı. Bağımsız geliştirildi.')}</h2><p>{choose('Nashi was inspired by Tangerine’s delightful drag-and-wheel interaction and adds new features and refined workflows. It is not affiliated with or endorsed by Tangerine or LEAP STUDIO.','Nashi, Tangerine’in keyifli sürükle ve çark etkileşiminden ilham aldı; yeni özellikler ve geliştirilmiş iş akışları ekliyor. Tangerine veya LEAP STUDIO ile bağlantılı değildir ve onlar tarafından desteklenmez.')}</p><a href="https://tangerineformac.com/">Tangerine ↗</a></section></main>
<footer><a class="brand" href="#">Nashi <span>◉</span></a><p>{choose('Original source under MIT. Third-party tools keep their own licenses.','Orijinal kaynak kod MIT lisanslıdır. Üçüncü taraf araçların kendi lisansları geçerlidir.')}</p><a href="https://github.com/orkunisitmak/nashi-app/blob/main/SECURITY.md">{choose('Security','Güvenlik')}</a><a href="https://github.com/orkunisitmak/nashi-app/blob/main/LICENSE">MIT</a></footer></body></html>'''
 out=R/'docs'/('tr/index.html' if tr else 'index.html');out.write_text(doc)
